349:   updateDrop(dt, game) {
350:     if (this.dropAlt === 0) this.dropAlt = this.pos.y;
351:     const ground = this.world.terrainHeight(this.pos.x, this.pos.z);
352:     const altitude = this.pos.y - ground;
353:     this.dropAlt = altitude;
354:     if (!this.chuteOpen && altitude < 55) {
355:       this.chuteOpen = true;
356:       this.parachute.visible = true;
357:       this.vel.y = -9;
358:       game.audio.tone(180, 0.3, 0.08, 'sawtooth', 90);
359:       game.ui?.toast('PARACHUTE DEPLOYED', 'STEER TOWARD A COMPOUND', 'gold');
360:     }
361: 
362:     const f = this.input.moveF;
363:     const r = this.input.moveR;
364:     const fwd = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
365:     const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
366:     const desired = fwd.multiplyScalar(f).add(right.multiplyScalar(r));
367:     if (desired.lengthSq() > 0) desired.normalize();
368:     const hSpeed = this.chuteOpen ? 7.2 : 19;
369:     this.vel.x = damp(this.vel.x, desired.x * hSpeed, 2.4, dt);
370:     this.vel.z = damp(this.vel.z, desired.z * hSpeed, 2.4, dt);
371:     const targetFall = this.chuteOpen ? -7.4 : -31;
372:     this.vel.y = damp(this.vel.y, targetFall, this.chuteOpen ? 3.2 : 1.4, dt);
373: 
374:     this.pos.x += this.vel.x * dt;
375:     this.pos.z += this.vel.z * dt;
376:     this.pos.y += this.vel.y * dt;
377:     const d = Math.hypot(this.pos.x, this.pos.z);
378:     if (d > 226) { this.pos.x *= 226 / d; this.pos.z *= 226 / d; }
379: 
380:     this.group.position.copy(this.pos);
381:     this.group.rotation.y = this.yaw;
382:     this.parachute.rotation.y = -this.yaw * 0.2;
383: 
384:     const g = this.world.terrainHeight(this.pos.x, this.pos.z);
385:     if (this.pos.y <= g + 0.08) {
386:       let x = this.pos.x, z = this.pos.z;
387:       let guard = 0;
388:       while (this.world.terrainHeight(x, z) < 0.45 && guard < 30) {
389:         x *= 0.94; z *= 0.94; guard++;
390:       }
391:       this.pos.set(x, Math.max(this.world.terrainHeight(x, z), 0.5), z);
392:       this.vel.set(0, 0, 0);
393:       this.mode = 'playing';
394:       this.grounded = true;
395:       this.chuteOpen = false;
396:       this.parachute.visible = false;
397:       this.weaponMount.visible = !this.buildMode;
398:       this.updateWeaponVisual();
399:       this.world.resolveCircle(this.pos, this.radius, this.height);
400:       this.group.position.copy(this.pos);
401:       game.audio.land();
402:       game.effects.dust(new THREE.Vector3(this.pos.x, this.pos.y + 0.1, this.pos.z));
403:       game.onLanded();
404:       this.pitch = -0.08;
405:     }
406:   }
