410:     const fwd = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
411:     const right = new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
412:     const desired = fwd.multiplyScalar(input.moveF).add(right.multiplyScalar(input.moveR));
413:     if (desired.lengthSq() > 1) desired.normalize();
414:     const moving = desired.lengthSq() > 0.001;
415: 
416:     this.aiming = input.aim && !this.buildMode;
417:     let speed = input.sprint && !this.aiming && !this.buildMode ? 7.3 : 5.15;
418:     if (this.aiming) speed = 3.1;
419:     if (input.crouch) speed = 2.6;
420:     if (this.buildMode) speed = 4.4;
421:     if (this.healTimer > 0) speed = 2.2;
422:     if (!moving) speed = 0;
423: 
424:     const accel = this.grounded ? 13 : 3.5;
425:     this.vel.x = damp(this.vel.x, desired.x * speed, accel, dt);
426:     this.vel.z = damp(this.vel.z, desired.z * speed, accel, dt);
