509:   fire(game) {
510:     const w = this.active;
511:     const def = this.activeDef;
512:     if (!w || !def) return;
513:     if (w.mag <= 0) {
514:       this.onReload(game);
515:       game.audio.click();
516:       if (this.reloadTimer <= 0) game.ui?.toast('OUT OF AMMO', 'FIND AMMUNITION', 'red');
517:       return;
518:     }
519:     w.mag--;
520:     this.fireCooldown = 60 / def.rpm;
521:     const spreadBase = def.spread * (1 + Math.min(1.8, this.moveSpeed * 0.11)) * (this.aiming ? 0.62 : 1) * (this.input.crouch ? 0.78 : 1);
522:     this.shotSpread = Math.min(0.12, this.shotSpread + spreadBase * 2.2);
523:     this.cameraKick = def.damage > 60 ? 0.07 : 0.022;
524:     this.shake = Math.max(this.shake, def.id === 'sniper' ? 0.2 : 0.055);
525: 
526:     const camera = game.camera;
527:     const origin = camera.position.clone();
528:     const baseDir = new THREE.Vector3();
529:     camera.getWorldDirection(baseDir);
530:     const model = this.weaponModels[def.id];
531:     const muzzle = new THREE.Vector3();
532:     if (model) {
533:       model.updateMatrixWorld(true);
534:       muzzle.set(0, 0.03, model.userData.muzzleZ);
535:       model.localToWorld(muzzle);
536:       const flash = model.userData.flash;
537:       if (flash) {
538:         flash.visible = true;
539:         flash.material.opacity = 1;
540:         flash.material.rotation = Math.random() * Math.PI * 2;
541:         clearTimeout(this._flashTimer);
542:         this._flashTimer = setTimeout(() => { flash.visible = false; }, 46);
543:       }
544:     } else {
545:       muzzle.copy(origin);
546:     }
547: 
548:     for (let p = 0; p < def.pellets; p++) {
549:       const dir = baseDir.clone();
550:       const spread = spreadBase * (def.pellets > 1 ? 1.9 : 1);
551:       dir.x += (Math.random() - 0.5) * spread * 2;
552:       dir.y += (Math.random() - 0.5) * spread * 2;
553:       dir.z += (Math.random() - 0.5) * spread * 2;
554:       dir.normalize();
555:       const hit = game.hitscan(origin, dir, def.range, this);
556:       const end = hit ? hit.point : origin.clone().add(dir.multiplyScalar(def.range));
557:       game.effects.tracer(muzzle, end, def.id === 'sniper' ? 0xffe9b0 : 0xffc76a, def.id === 'sniper' ? 1 : 0.8);
558:       if (hit) {
559:         if (hit.bot) {
560:           const falloff = Math.max(0.62, 1 - hit.distance / def.range * 0.38);
561:           const dmg = def.damage * falloff * (hit.head ? def.headshot : 1);
562:           hit.bot.damage(dmg, game, this, def, hit.head);
563:           this.damageDealt += dmg;
564:           game.ui?.hitmarker(hit.head, hit.bot.health <= 0);
565:           game.audio.hit(hit.head);
566:           game.effects.blood(hit.point, hit.head);
567:         } else {
568:           game.effects.impact(hit.point, hit.kind);
569:         }
570:       }
571:     }
572: 
573:     this.pitch += this.cameraKick * (0.75 + Math.random() * 0.5);
574:     this.yaw += (Math.random() - 0.5) * this.cameraKick * 0.35;
575:     this.clampPitch();
576:     game.audio.shot(def.sound, 0, 0, 1);
577:     if (w.mag === 0) game.ui?.toast('MAGAZINE EMPTY', 'PRESS R TO RELOAD', 'red');
578:   }
