580:   updateBuild(dt, game) {
581:     const type = this.buildType;
582:     for (const [key, ghost] of Object.entries(this.ghosts)) ghost.visible = key === type;
583:     const ghost = this.ghosts[type];
584:     const snapped = Math.round(this.yaw / (Math.PI / 2)) * (Math.PI / 2);
585:     const forward = new THREE.Vector3(-Math.sin(this.yaw), 0, -Math.cos(this.yaw));
586:     const dist = type === 'wall' ? 3.5 : type === 'ramp' ? 3.2 : 3.1;
587:     let x = this.pos.x + forward.x * dist;
588:     let z = this.pos.z + forward.z * dist;
589:     x = Math.round(x / 2) * 2;
590:     z = Math.round(z / 2) * 2;
591: 
592:     const support = this.world.surfaceHeight(this.pos.x, this.pos.z, this.pos.y);
593:     let y;
594:     if (type === 'wall') y = this.world.surfaceHeight(x, z, this.pos.y + 0.75);
595:     else if (type === 'floor') y = support + (this.pitch > 0.16 ? 2.9 : 0.02);
596:     else y = support + 0.02;
597: 
598:     const dx = x - this.pos.x, dz = z - this.pos.z;
599:     const rounded = Math.round(snapped / (Math.PI / 2)) * (Math.PI / 2);
600:     ghost.position.set(x, y, z);
601:     ghost.rotation.y = rounded;
602: 
603:     const insideIsland = Math.hypot(x, z) < 220;
604:     const ground = this.world.terrainHeight(x, z);
605:     let blocked = false;
606:     const cy = y + (type === 'wall' ? 1.2 : 0.4);
607:     for (const box of this.world.colliders) {
608:       if (x > box.minX - 0.3 && x < box.maxX + 0.3 && z > box.minZ - 0.3 && z < box.maxZ + 0.3 && cy > box.minY && cy < box.maxY) {
609:         blocked = true;
610:         break;
611:       }
612:     }
613:     const tooFar = Math.hypot(dx, dz) > 7;
614:     const valid = insideIsland && ground > 0.4 && !blocked && !tooFar && this.materials >= BUILD_COST;
615:     this.buildValid = valid;
616:     setBuildGhostValid(ghost, valid);
617:     this.buildTransform = { x, z, y, ry: rounded, type };
618:     game.ui?.updateBuildValid(valid, this.materials);
619:   }
