644:   pickup(item, game) {
645:     const type = item.type;
646:     if (type === 'weapon') {
647:       const def = weaponFor(item.weaponId);
648:       const same = this.weapons.findIndex(w => w && w.id === item.weaponId);
649:       if (same >= 0) {
