651:         w.reserve = Math.min(def.reserveMax, w.reserve + def.pickupAmmo);
652:         game.ui?.toast(def.name, `+${def.pickupAmmo} AMMO`, 'gold');
653:       } else {
654:         const empty = this.weapons.findIndex(w => !w);
655:         const slot = empty >= 0 ? empty : this.currentSlot;
656:         this.weapons[slot] = { id: item.weaponId, mag: def.mag, reserve: def.pickupAmmo };
657:         if (empty < 0 || slot === this.currentSlot) {
658:           this.currentSlot = slot;
659:           this.updateWeaponVisual();
660:         }
661:         game.ui?.toast(def.name, 'WEAPON ACQUIRED', 'gold');
662:       }
663:     } else if (type === 'ammo') {
664:       const w = this.active;
665:       if (w) {
666:         const def = weaponFor(w.id);
667:         const add = Math.max(def.pickupAmmo, 20);
668:         const before = w.reserve;
669:         w.reserve = Math.min(def.reserveMax, w.reserve + add);
670:         game.ui?.toast('AMMUNITION', `+${w.reserve - before} RESERVE`, 'gold');
671:       } else {
672:         game.ui?.toast('AMMUNITION', 'NO WEAPON EQUIPPED', 'red');
673:         return;
674:       }
675:     } else if (type === 'med') {
676:       if (this.meds >= 3) {
677:         game.ui?.toast('MEDKITS FULL', '3 MAX', 'red');
678:         return;
679:       }
680:       this.meds = Math.min(3, this.meds + 1);
681:       game.ui?.toast('FIELD MEDKIT', 'PRESS F TO HEAL', 'gold');
682:     } else if (type === 'armor') {
683:       if (this.armor >= 100) {
684:         game.ui?.toast('ARMOR FULL', '100 MAX', 'red');
685:         return;
686:       }
687:       this.armor = Math.min(100, this.armor + 50);
688:       game.ui?.toast('BALLISTIC PLATE', '+50 ARMOR', 'gold');
689:     }
690:     this.world.removeLoot(item);
691:     game.audio.pickup();
692:   }
