712:       this.parachute.visible = false;
713:       this.model.rotation.x = -Math.PI / 2;
714:       this.model.position.y = 0.42;
715:       for (const ghost of Object.values(this.ghosts)) ghost.visible = false;
716:       game.onPlayerDeath(attacker);
