720:   animate(dt) {
721:     if (this.mode === 'drop') {
722:       this.leftArm.rotation.z = -1.1 + Math.sin(this.walkPhase) * 0.05;
723:       this.rightArm.rotation.z = 1.1 - Math.sin(this.walkPhase) * 0.05;
724:       this.leftArm.rotation.x = 0;
725:       this.rightArm.rotation.x = 0;
726:       this.leftLeg.rotation.x = 0.18;
727:       this.rightLeg.rotation.x = -0.12;
728:       this.walkPhase += dt * 2;
729:       return;
730:     }
731:     if (this.dead) return;
732:     const speed = this.moveSpeed;
733:     if (speed > 0.25 && this.grounded) {
734:       this.walkPhase += dt * (5.2 + speed * 1.15);
735:       const swing = Math.min(0.9, 0.32 + speed * 0.075);
736:       this.leftLeg.rotation.x = Math.sin(this.walkPhase) * swing;
737:       this.rightLeg.rotation.x = -Math.sin(this.walkPhase) * swing;
738:       this.leftArm.rotation.x = -Math.sin(this.walkPhase) * swing * 0.65;
739:       this.rightArm.rotation.x = Math.sin(this.walkPhase) * swing * 0.65;
740:     } else {
741:       this.walkPhase += dt * 1.4;
742:       const breathe = Math.sin(this.walkPhase) * 0.035;
743:       this.leftLeg.rotation.x = damp(this.leftLeg.rotation.x, 0, 8, dt);
744:       this.rightLeg.rotation.x = damp(this.rightLeg.rotation.x, 0, 8, dt);
745:       this.leftArm.rotation.x = damp(this.leftArm.rotation.x, breathe, 8, dt);
746:       this.rightArm.rotation.x = damp(this.rightArm.rotation.x, breathe, 8, dt);
747:     }
748:     this.leftArm.rotation.z = this.aiming ? -0.24 : 0;
749:     this.rightArm.rotation.z = this.aiming ? -0.18 : 0;
750:     if (this.aiming) {
751:       this.rightArm.rotation.x = -1.2;
752:       this.leftArm.rotation.x = -1.34;
753:     }
754:     if (!this.grounded) {
755:       this.leftLeg.rotation.x = 0.35;
756:       this.rightLeg.rotation.x = -0.2;
757:     }
758:   }
