760:   updateCamera(camera, dt) {
761:     const pivot = new THREE.Vector3(this.pos.x, this.pos.y + 1.58, this.pos.z);
762:     const forward = new THREE.Vector3(
763:       -Math.sin(this.yaw) * Math.cos(this.pitch),
764:       Math.sin(this.pitch),
765:       -Math.cos(this.yaw) * Math.cos(this.pitch),
