.minimap-wrap { position: absolute; top: calc(79px + var(--safe-t)); right: calc(26px + var(--safe-r)); width: 188px; pointer-events: auto; cursor: pointer; }
.minimap-frame {
  position: relative; width: 100%; aspect-ratio: 1; overflow: hidden;
  background: rgba(7, 11, 9, 0.84);
  border: 1px solid rgba(241, 234, 217, 0.28);
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
}
.minimap-frame canvas { width: 100%; height: 100%; display: block; }
.minimap-scan {
  position: absolute; inset: 0; pointer-events: none;
  background: repeating-linear-gradient(180deg, transparent 0 3px, rgba(6, 12, 10, 0.19) 3px 4px);
  box-shadow: inset 0 0 40px rgba(0, 0, 0, 0.28);
}
.corner { position: absolute; width: 9px; height: 9px; border-color: var(--gold); border-style: solid; opacity: 0.9; }
.c1 { top: 4px; left: 4px; border-width: 1px 0 0 1px; }
.c2 { top: 4px; right: 4px; border-width: 1px 1px 0 0; }
.c3 { bottom: 4px; left: 4px; border-width: 0 0 1px 1px; }
.c4 { bottom: 4px; right: 4px; border-width: 0 1px 1px 0; }
.minimap-meta {
  display: flex; justify-content: space-between; align-items: center; gap: 6px;
  padding: 7px 9px; background: rgba(8, 12, 10, 0.85);
  border: 1px solid rgba(241, 234, 217, 0.16); border-top: 0;
}
.minimap-meta > span:first-child { font-size: 12px; letter-spacing: 0.14em; font-weight: 600; }
.minimap-meta .coord { font-family: var(--mono); font-size: 6px; letter-spacing: 0.04em; color: var(--dim); }

.killfeed {
  position: absolute; top: calc(79px + 234px + var(--safe-t)); right: calc(26px + var(--safe-r));
  width: 300px; display: flex; flex-direction: column; align-items: flex-end; gap: 5px;
}
.kill-entry {
  display: flex; align-items: center; gap: 7px; max-width: 100%;
  padding: 6px 9px; background: linear-gradient(90deg, rgba(8, 12, 10, 0.55), rgba(8, 12, 10, 0.88));
  border-right: 2px solid rgba(241, 234, 217, 0.3);
  font-family: var(--mono); font-size: 8px; letter-spacing: 0.05em; color: var(--muted);
